import{_ as r,o as t,c as s,a4 as o,ap as n,aq as i,ar as l,as as e,at as h,au as d,av as p}from"./chunks/framework.CmuCl-jw.js";const v=JSON.parse('{"title":"The Apps","description":"","frontmatter":{},"headers":[],"relativePath":"apps/index.md","filePath":"apps/index.md"}'),g={name:"apps/index.md"};function c(m,a,u,f,b,y){return t(),s("div",null,[...a[0]||(a[0]=[o('<h1 id="the-apps" tabindex="-1">The Apps <a class="header-anchor" href="#the-apps" aria-label="Permalink to “The Apps”">​</a></h1><p>Arcsecond.local brings the whole life of an astronomical observatory into a single, self-hosted platform, organised into <strong>four apps</strong>. The first three follow the three phases of the observation lifecycle; the fourth is what every multi-user install gets for free.</p><ul><li><strong><a href="#night-studio">Night Studio</a></strong> — prepare observations.</li><li><strong><a href="#control-room">Control Room</a></strong> — acquire new data and automate your nights.</li><li><strong><a href="#data-grand-central">Data Grand Central</a></strong> — store, package and share your data.</li><li><strong><a href="#observatory-headquarters">Observatory Headquarters</a></strong> — run your observatory as a team.</li></ul><h2 id="night-studio" tabindex="-1">Night Studio <a class="header-anchor" href="#night-studio" aria-label="Permalink to “Night Studio”">​</a></h2><p><a href="/apps/night-studio/">Night Studio</a> gathers everything Arcsecond.local offers to prepare your observations — powerful visualisations to decide what to observe, when and from where.</p><h3 id="night-explorer" tabindex="-1"><span style="display:inline-flex;align-items:center;gap:0.5rem;"><img src="'+n+'" width="40"><span>Night Explorer</span></span> <a class="header-anchor" href="#night-explorer" aria-label="Permalink to “Night Explorer”">​</a></h3><p><a href="/apps/night-studio/#night-explorer">Night Explorer</a>, a.k.a. <strong>iObserve</strong>, our flagship decision-making tool for planning and scheduling observations. Used by many astronomers worldwide.</p><h3 id="transit-browser" tabindex="-1"><span style="display:inline-flex;align-items:center;gap:0.5rem;"><img src="'+i+'" width="40"><span>Transit Browser</span></span> <a class="header-anchor" href="#transit-browser" aria-label="Permalink to “Transit Browser”">​</a></h3><p>The <a href="/apps/night-studio/#transit-browser">Transit Browser</a> lets you browse the currently accessible exoplanet transits for any time and location, plus non-regular transits and other transiting objects.</p><h3 id="target-lists" tabindex="-1"><span style="display:inline-flex;align-items:center;gap:0.5rem;"><img src="'+l+'" width="40"> Target Lists</span> <a class="header-anchor" href="#target-lists" aria-label="Permalink to “Target Lists”">​</a></h3><p><a href="/apps/night-studio/#target-lists">Target Lists</a> are a simple way to organise and manage your observing targets — to plan observations, track progress, and share with colleagues.</p><h3 id="finding-chart-editor" tabindex="-1"><span style="display:inline-flex;align-items:center;gap:0.5rem;"><img src="'+e+'" width="40"> Finding Chart Editor</span> <a class="header-anchor" href="#finding-chart-editor" aria-label="Permalink to “Finding Chart Editor”">​</a></h3><p>The <a href="/apps/night-studio/#finding-chart-editor">Finding Chart Editor</a> prepares detailed, highly customised finding charts, with custom overlays from large instruments or even your own.</p><p><br><br></p><h2 id="control-room" tabindex="-1">Control Room <a class="header-anchor" href="#control-room" aria-label="Permalink to “Control Room”">​</a></h2><p>The <a href="/apps/control-room/">Control Room</a> is the app to acquire new data and automate your observing nights, talking directly to the equipment on (or reachable from) your host.</p><p>It covers <strong>Equipment Setup</strong>, the <strong>Observer Console</strong>, the <strong>Night Scheduler</strong>, the <strong>Observing Queue</strong> and the <strong>Calibration Manager</strong>. It is the most recent of the four apps and under active development.</p><p><br><br></p><h2 id="data-grand-central" tabindex="-1">Data Grand Central <a class="header-anchor" href="#data-grand-central" aria-label="Permalink to “Data Grand Central”">​</a></h2><p><a href="/apps/data/">Data Grand Central</a> stores, organises, packages and shares your data — on <strong>your own infrastructure</strong>, with no cloud tier and no storage quota.</p><h3 id="data-management" tabindex="-1"><span style="display:inline-flex;align-items:center;gap:0.5rem;"><img src="'+h+'" width="40"> Data Management</span> <a class="header-anchor" href="#data-management" aria-label="Permalink to “Data Management”">​</a></h3><p><a href="/apps/data/datasets">Datasets</a> are the virtual folders containing data. They group (and let you easily download) data files that share a common source or interest.</p><p><a href="/apps/data/storage">Storage</a> is where your data lives on the host. <a href="/apps/data/external-storages">External Storages</a> let you attach data you already own (S3, Dropbox, FTP/SFTP, local disk, observatory archives), read-only, so Arcsecond.local indexes it alongside its own data — consolidating your Follow-Up Targets and reconstructing past Night Logs.</p><h3 id="data-packages" tabindex="-1"><span style="display:inline-flex;align-items:center;gap:0.5rem;"><img src="'+d+'" width="40"> Data Packages</span> <a class="header-anchor" href="#data-packages" aria-label="Permalink to “Data Packages”">​</a></h3><p><a href="/apps/data/datapackages">Data Packages</a> are custom packages of Datasets to be shared — within your organisation (e.g. for visiting observers), with other astronomers, or with the public.</p><h3 id="data-file-browser" tabindex="-1"><span style="display:inline-flex;align-items:center;gap:0.5rem;"><img src="'+p+'" width="40"> Data &amp; File Browser</span> <a class="header-anchor" href="#data-file-browser" aria-label="Permalink to “Data &amp; File Browser”">​</a></h3><p><a href="/apps/data/filebrowser">File Browser</a> browses every data file known to the install, whether stored locally or on an attached External Storage.</p><h3 id="follow-up-targets" tabindex="-1"><span style="display:inline-flex;align-items:center;gap:0.5rem;"><img src="'+e+'" width="40"> Follow-Up Targets</span> <a class="header-anchor" href="#follow-up-targets" aria-label="Permalink to “Follow-Up Targets”">​</a></h3><p><a href="/apps/followup/">Follow-Up Targets</a> automatically tracks every target you have observed. Arcsecond.local maintains the list from your Night Logs and the ones it reconstructs from your stored and attached data.</p><p><br><br></p><h2 id="observatory-headquarters" tabindex="-1">Observatory Headquarters <a class="header-anchor" href="#observatory-headquarters" aria-label="Permalink to “Observatory Headquarters”">​</a></h2><p>Every Arcsecond.local install is <strong>multi-user by design</strong>. <a href="/apps/headquarters/">Observatory Headquarters</a> is the app that manages that shared life: an unlimited number of members, a clear <a href="/apps/headquarters/permissions">5-level permission scheme</a>, data sharing, and an observatory-wide schedule and history.</p>',32)])])}const x=r(g,[["render",c]]);export{v as __pageData,x as default};
